import torch, math
def deform(t, coef, T):
    k = torch.arange(1, coef.shape[-1] // 2 + 1, dtype=t.dtype)
    w = 2 * math.pi * k / T
    a, b = coef.chunk(2, dim=-1)
    return (a * torch.cos(w * t) + b * torch.sin(w * t)).sum(-1)

def drift(s, d):
    # s: 空间门控(s(xr)=0), d: 时间幅度
    return s * d  # 参考视图处 s=0 => 无修正
